def transform(grid):
    H = len(grid)
    W = len(grid[0])
    bg = grid[0][0]
    seen = [[False] * W for _ in range(H)]
    out = [row[:] for row in grid]
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    for r in range(H):
        for c in range(W):
            if seen[r][c] or grid[r][c] == bg:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            min_r = max_r = r
            min_c = max_c = c
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                if y < min_r:
                    min_r = y
                if y > max_r:
                    max_r = y
                if x < min_c:
                    min_c = x
                if x > max_c:
                    max_c = x
                for dy, dx in dirs:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        stack.append((ny, nx))

            if min_c == max_c:
                continue

            keep = set()
            for y, x in cells:
                mx = min_c + max_c - x
                if min_c <= mx <= max_c and grid[y][mx] == color:
                    keep.add((y, x))
                    keep.add((y, mx))

            for y, x in cells:
                if (y, x) not in keep:
                    out[y][x] = bg
    return out

def transform(grid):
    H = len(grid)
    W = len(grid[0])

    def background(g):
        counts = {}
        for row in g:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        return max(sorted(counts), key=lambda c: counts[c])

    def clean(color, cells, bg):
        cells = list(cells)
        if not cells:
            return []
        s = 1
        while True:
            changed = False
            for r, c in cells:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == bg:
                            # Count 4-neighbours of same color within the candidate shape.
                            n = 0
                            for a, b in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                                if (r + a, c + b) in cells:
                                    n += 1
                            if n == 0:
                                cells.remove((r, c))
                                changed = True
                                break
                    if changed:
                        break
                if changed:
                    break
            s += 1
            if not changed or s > 60:
                break
        return cells

    bg = background(grid)
    out = [row[:] for row in grid]

    for color in set(v for row in grid for v in row):
        if color == bg:
            continue
        cells = set((r, c) for r in range(H) for c in range(W) if grid[r][c] == color)
        for r, c in cells:
            out[r][c] = bg
        for r, c in clean(color, cells, bg):
            out[r][c] = color
    return out

